namespace ToneCustoms.ShellStudio.Bridges;
public sealed record ToolStatus(string Name,bool Found,string? Path,string? Version);
public sealed class DependencyDetector { public IEnumerable<ToolStatus> Scan(){yield return FindBlender();yield return FindExecutable("CodeWalker","CodeWalker.exe");var s=new SollumzVersionDetector().Detect();yield return new("Sollumz",s.Found,s.Root,s.Version);}ToolStatus FindBlender(){var root=@"C:\Program Files\Blender Foundation";var exe=Directory.Exists(root)?Directory.GetFiles(root,"blender.exe",SearchOption.AllDirectories).OrderByDescending(x=>x).FirstOrDefault():null;return new("Blender",exe!=null,exe,null);}ToolStatus FindExecutable(string n,string exe){var p=(Environment.GetEnvironmentVariable("PATH")??"").Split(';',StringSplitOptions.RemoveEmptyEntries).Select(x=>Path.Combine(x,exe)).FirstOrDefault(File.Exists);return new(n,p!=null,p,null);} }
